            planes.append(('real',ev[i],np.real(V[:,i])[:,None])); continue
        B=np.stack([V[:,i].real,V[:,i].imag],1); B=np.linalg.qr(B)[0]
        planes.append(('cplx',ev[i],B))
print("planes:",[(p[0],round(abs(p[1]),2),round(np.angle(p[1])/np.pi,2)) for p in planes])
def plane_stats(A):
    out=[]
